// The one seam between the TS package and the napi addon (`../native/index.js`, generated by
// `napi build`). Loaded lazily so importing `@brust/core` never needs the addon (a route file is
// imported by `brust build` and by tests); tests swap the binding with `setNative` instead of
// `mock.module`, which leaks process-wide.

/** Shapes of `crates/brust-napi` (plan D1, Task 1 + Task 2). Written by hand so this file
 * typechecks before Task 2's exports exist in the generated `native/index.d.ts`. */
export interface InvalidateArgs {
  key?: string
  tags?: string[]
  path?: string
  method?: string
}
export interface InvalidateResult {
  l1Removed: number
  jobRemoved: number
}
export interface StartOptions {
  host: string
  port: number
  distDir: string
  workers: number
  claimTimeoutMs?: number
  callTimeoutMs?: number
  /** tokio I/O threads; absent = one per core. */
  workerThreads?: number
  l1Capacity?: number
  jobCacheCapacity?: number
  generator?: string
  /** Global CORS policy; absent = CORS off. Boot error `cors: …` when invalid. */
  cors?: CorsOptions
  /** The actions subtree (M3-F A3); absent = no actions. Boot error `actions: …` when invalid. */
  actions?: ActionsOptions
  /** The cache adapter (`manifest.cache`); absent = none (byte-identical server). */
  l2?: L2Options
}
/** napi `NapiL2Options`; defaults 50 ms, 1048576 bytes. */
export interface L2Options {
  adapter: string
  getTimeoutMs?: number
  maxBodyBytes?: number
  namespace: string
  buildId: string
}
/** napi `NapiCorsOptions` (camelCase keys; snake_case keys are silently dropped). */
export interface CorsOptions {
  origins: string[]
  methods?: string[]
  headers?: string[]
  exposeHeaders?: string[]
  credentials?: boolean
  maxAgeSeconds?: number
}
/** napi `NapiActionsOptions`; defaults `/_brust/action`, 1048576, 8388608. */
export interface ActionsOptions {
  prefix?: string
  maxBodyBytes?: number
  /** F82: response body cap (bytes). Default 8388608. */
  maxResponseBytes?: number
  /** F87: cross-site mutating requests. Default `reject`. */
  crossSite?: 'reject' | 'allow'
}
export type WorkerFn = (kind: 'loader' | 'jobs' | 'fetch' | 'cache', requestJson: string, slot: number) => Promise<number>
export interface NativeBinding {
  startServer(opts: StartOptions): void
  registerWorker(buf: Uint8Array, slots: number, f: WorkerFn): number
  untilReady(timeoutMs: number): Promise<void>
  beginDrain(timeoutMs: number): Promise<void>
  cacheInvalidate(args: InvalidateArgs): InvalidateResult
  cacheStats(): string
  localAddr(): string
  /** M3-P P6 — see crates/brust-napi/src/server.rs `plan_jobs`. Never throws. */
  planJobs(slot: number, len: number): string
  /** F82 — the heap request body of the in-flight `fetch` call, once; null if none. Never throws. */
  takeFetchBody(slot: number): Uint8Array | null
  /** F82 — hand Rust a response body too large for the slot; false = declined. Never throws. */
  putFetchReply(slot: number, body: Uint8Array): boolean
  /** cache adapter R10 — a foreign broadcast event: tier 1 + the floor at `seq`; never re-published. */
  cacheReplay(args: InvalidateArgs, seq: number | null): InvalidateResult
  /** cache adapter R9 — bump `stats.l2[name]`; false = unknown name / no adapter / no server. Never throws. */
  cacheL2Count(name: string): boolean
  /** cache adapter R10 — drop both tier-1 caches (a broadcast gap); the L1 entries removed. */
  cacheClear(): number
}

let binding: NativeBinding | null = null

/** The addon, loaded on first use. Throws if the addon is not built for this platform. */
export function native(): NativeBinding {
  binding ??= require('../native/index.js') as NativeBinding
  return binding
}

/** Replace the binding (tests). Returns the previous one so a test can restore it;
 * `null` restores lazy loading. */
export function setNative(b: NativeBinding | null): NativeBinding | null {
  const prev = binding
  binding = b
  return prev
}

export const startServer = (opts: StartOptions): void => native().startServer(opts)
export const registerWorker = (buf: Uint8Array, slots: number, f: WorkerFn): number => native().registerWorker(buf, slots, f)
export const untilReady = (timeoutMs: number): Promise<void> => native().untilReady(timeoutMs)
export const beginDrain = (timeoutMs: number): Promise<void> => native().beginDrain(timeoutMs)
export const cacheInvalidate = (args: InvalidateArgs): InvalidateResult => native().cacheInvalidate(args)
export const cacheStats = (): string => native().cacheStats()
export const localAddr = (): string => native().localAddr()
export const planJobs = (slot: number, len: number): string => native().planJobs(slot, len)
export const takeFetchBody = (slot: number): Uint8Array | null => native().takeFetchBody(slot)
export const putFetchReply = (slot: number, body: Uint8Array): boolean => native().putFetchReply(slot, body)
export const cacheReplay = (args: InvalidateArgs, seq: number | null): InvalidateResult => native().cacheReplay(args, seq)
export const cacheL2Count = (name: string): boolean => native().cacheL2Count(name)
export const cacheClear = (): number => native().cacheClear()
